using CCAP.Application.Common.Validation;namespace CCAP.Application.Features.Patients.Commands.AddCareLog;
public sealed class AddCareLogCommandValidator:IRequestValidator<AddCareLogCommand>{public void Validate(AddCareLogCommand r){if(r.PatientId==Guid.Empty)throw new ArgumentException("Patient ID is required.");if(string.IsNullOrWhiteSpace(r.LogType))throw new ArgumentException("Care log type is required.");if(string.IsNullOrWhiteSpace(r.Item))throw new ArgumentException("Item is required.");if(r.Item.Length>200)throw new ArgumentException("Item cannot exceed 200 characters.");if(r.Quantity<0)throw new ArgumentException("Quantity cannot be negative.");if((r.Unit?.Length??0)>50)throw new ArgumentException("Unit cannot exceed 50 characters.");if((r.Notes?.Length??0)>2000)throw new ArgumentException("Notes cannot exceed 2000 characters.");if(r.RecordedByUserId==Guid.Empty)throw new ArgumentException("Recorded by user ID is required.");}}
